"""Procurement answers added from the 30 October GEO action plan.
Brief: English B2B buyers; answer the decision, compare alternatives, show a
labelled purchasing example and connect it to existing specifications and RFQ.
No new company credentials, customer stories or performance figures are asserted.
"""
GUIDES = [
 dict(slug='straight-vs-reverse-tuck-end', title='Straight vs reverse tuck end boxes: how do they differ?',
 description='Compare tuck-flap direction, artwork layout, packing access and sample checks before specifying a custom folding carton.',
 answer='Straight tuck end cartons have top and bottom tuck closures facing the same direction; reverse tuck end cartons have them facing opposite directions. Choose by the opening, artwork panels, packing method and approved dieline. Neither name establishes board strength, product retention or shipping performance. A structural sample with the actual contents is the useful next step.',
 chapters=[('Read the flat dieline first','Identify the front panel, glue seam, top opening and bottom closure on the drawing. Viewed as a flat blank, a carton can be confusing when the artwork has been rotated. Ask for a labelled drawing and compare it with an assembled sample rather than interpreting the flap arrangement from a product photograph.'),('Keep artwork clear of working areas','Check the front-facing panel, barcode, mandatory product copy and any print that crosses folds. Mark glue areas and finish positions separately. A structure change can move a closure or seam relative to your design, so do not reuse the artwork from a different carton without checking its panel map.'),('Trial the packing and opening sequence','Pack the actual bottle, jar or tube in the intended orientation. Check insertion, tuck engagement, clearance and removal. Review any inner support separately. If the retail carton will travel by courier, specify outer protection and review the finished parcel; a tuck closure is not a parcel-test result.')],
 example='Illustrative buying scenario: a skincare buyer compares two unprinted cartons for the same capped tube. One has aligned tuck closures and the other has opposing closures. The buyer marks the display front, packs the tube, checks how the bottom is closed and removes the product through the top. The selected drawing is then given a revision before artwork is applied. This is a planning example, not a completed customer order.',
 rows=[('Straight tuck end','Same-direction tuck closures; confirm which face carries each closure and the intended opening.'),('Reverse tuck end','Opposite-direction tuck closures; inspect the panel map before positioning artwork.'),('Either structure','Review board, fit, retention, assembly and outer shipment protection independently.')],
 mistakes=['Choosing the flap direction from the decorated front photograph alone.','Treating a closure name as a load rating.','Moving artwork between drawings without matching panels.'],
 checks=['Mark the front, top and glue seam on the approved drawing.','Trial the actual product and any insert.','Keep artwork and dieline revisions together.'],
 faq=[('Is straight tuck end always stronger?','No. Closure direction alone does not specify strength. Board, dimensions, construction, packed load and handling determine which checks are needed.'),('Can the same artwork fit both structures?','Only after the panel map, folds, glue zones and closure positions have been reviewed. Request a revised proof if the dieline changes.'),('Should I send internal or external dimensions?','State which convention you mean and include units. Send the actual product dimensions and ask for a fit sample before approving the finished size.'),('Do I need a rigid box instead?','Compare the presentation, packing process, insert and shipment volume. A rigid box and a folding carton solve different structural and presentation needs.')],
 links=['/products/custom-boxes/folding-cartons/','/guides/folding-cartons-vs-rigid-boxes/']),
 dict(slug='packaging-materials-explained', title='Packaging materials: paperboard, greyboard or corrugated?',
 description='Understand paperboard, greyboard and corrugated construction, then compare product fit, printing surfaces and sample requirements.',
 answer='Paperboard is a starting point for cut-and-fold retail cartons; greyboard commonly provides the core of wrapped rigid boxes; corrugated board combines liners and fluting for a different structural direction. Choose the complete construction around the product, packing method and distribution route. Material names alone do not specify thickness, strength, recycled content or suitability for contact with a product.',
 chapters=[('Separate the core from the visible surface','A rigid gift box can have a greyboard core with a separate decorative wrap. A printed corrugated pack can combine a print-facing sheet with a fluted construction. When comparing quotes, list the layers and finishes rather than assuming the exterior image identifies the complete material.'),('Compare dimensions and assembly','Board thickness and fold behavior affect usable space, creases and closures. Measure the product in its final orientation, including protective components. Request a sample of the proposed construction and check how it is packed, stacked and removed. Specify outer-size limits as well as internal fit when shelf or freight constraints matter.'),('Ask for relevant evidence','If a project needs a sourcing, contact or performance claim, identify the exact construction and intended use first. Ask which documents and tests address that requirement. An attractive kraft appearance does not establish recycled content, and a paper specification does not establish finished-package performance.')],
 example='Illustrative buying scenario: a buyer needs a retail carton and an outer shipping pack for the same glass jar. Paperboard is reviewed for the printed retail unit; corrugated construction and cushioning are reviewed for the shipping configuration. A separate greyboard gift-box option is costed for a presentation set. The buyer compares the complete assembled packages rather than choosing one material name for every layer.',
 rows=[('Paperboard carton','Review board grade, thickness, creasing, printing and product retention.'),('Greyboard rigid box','Review core, wrap, corners, insert and assembled shipment volume.'),('Corrugated pack','Review liners, flute construction, closure, cushioning and the distribution test plan.')],
 mistakes=['Comparing only paper weight while ignoring construction.','Calling a kraft-colored surface proof of recycled content.','Using a material sample as a finished-package test result.'],
 checks=['List core, outer surface, inner surface and coatings.','Record thickness and size conventions in the specification.','Match requested documentation to the agreed material and order.'],
 faq=[('Is heavier paper always better?','Weight is one input. Structure, fiber, thickness, folds, adhesives and intended load also matter. Compare the assembled package in use.'),('Can corrugated board be used for presentation?','It can be considered where its structure and surface suit the design. Review the opening, printing and insert rather than assuming presentation requires a rigid box.'),('Does kraft mean recyclable?','Appearance alone does not establish recyclability. Review the complete construction and the collection system relevant to the intended market.'),('What should I send for material selection?','Send product dimensions and weight, contact conditions, required appearance, quantity, packing method and delivery route. Include any documentation requirement.')],
 links=['/materials/','/guides/internal-vs-external-box-dimensions/']),
 dict(slug='custom-packaging-moq', title='Custom packaging MOQ: what determines the order quantity?',
 description='Learn how size, artwork versions, material, tooling and finishing affect custom packaging MOQ and the basis of a comparable quotation.',
 answer='Custom packaging minimum order quantity depends on the material, structure, print setup, finishing and quantity per size and artwork. PackHubGlobe catalog references start at 500 pieces; the written quotation confirms the split and final specification. Treat a displayed starting quantity as an enquiry starting point, rather than permission to combine unrelated sizes and designs into one production run.',
 chapters=[('Count the versions before requesting a price','List each size, artwork, color direction and packaging component separately. A total quantity for a product range does not show how many production setups are involved. Ask the supplier to identify shared tooling or material opportunities, but keep each line item visible in the comparison.'),('Compare total cost on the same basis','Unit price can exclude tooling, proofs, samples, packing or freight. Request the same specification and delivery basis when comparing options. If a smaller run is possible, review the resulting setup cost per item and the cash committed to the complete order, rather than looking only at the quoted unit price.'),('Simplify the brief where the design allows','A shared carton size or fewer artwork variants may create a different production proposal. Ask what changes if the structure, finish or version count is simplified. Do not assume a lower quantity will keep the same material, finishing route or production schedule; record any substitution explicitly.')],
 example='Illustrative buying scenario: an apparel buyer plans bags for three product ranges. The buyer first requests separate quantities by size and printed design, then asks for an alternative using a common bag size and shared artwork. Both proposals include samples, setup and shipment assumptions. The comparison identifies the commercial effect of simplification without claiming a universal discount or guaranteed smaller minimum.',
 rows=[('Quantity per design','State the number for each artwork and size, not just the overall campaign total.'),('Setup and finishing','Separate tooling, print preparation, special finishes and sample charges where applicable.'),('Repeat order','Confirm whether the previous tools, material and artwork remain usable; do not assume identical terms.')],
 mistakes=['Combining all sizes into one unexplained quantity.','Assuming a catalog MOQ is a finished quotation.','Ordering excess stock solely to reduce unit price.'],
 checks=['Create a component and version list.','Record one specification and delivery basis for each comparison.','Confirm quantity tolerances and commercial terms in writing.'],
 faq=[('Can I mix designs within 500 pieces?','Ask for a quote showing the proposed split. The catalog starting quantity does not automatically cover multiple designs or sizes.'),('Does a reorder have the same MOQ?','Confirm the current specification, artwork, tools and material plan. A previous order is useful context, not an automatic commitment to unchanged terms.'),('How can I evaluate a larger order?','Compare total cash, storage, expected use, version changes and freight as well as unit price. Request alternative quantities on the same specification.'),('Is there a fixed public price list?','Custom prices require the structure, dimensions, material, artwork, quantity and delivery basis. Send these details for a project quotation.')],
 links=['/catalog/','/guides/packaging-quote-checklist/']),
 dict(slug='foil-vs-spot-uv-vs-embossing', title='Foil vs spot UV vs embossing: choose a packaging finish',
 description='Compare metallic foil, selective gloss and raised relief by visual effect, artwork preparation, registration and physical sample review.',
 answer='Foil stamping adds a foil effect to selected areas; spot UV adds a localized coated effect; embossing creates raised relief in the substrate. Choose by the intended visual or tactile result, the material and the artwork. These finishes are not interchangeable, and a screen mockup cannot reproduce their full appearance or feel. Review a physical reference before approval.',
 chapters=[('Define the effect before naming the process','A metallic logo, a glossy pattern and a raised emblem ask for different production decisions. Share a reference and mark the area that should change. Explain whether the priority is reflectivity, contrast, touch or a subtle brand detail. The proposed process should be reviewed against the selected surface.'),('Separate artwork layers and working areas','Keep finish positions identifiable from printed artwork. Ask the production team to review fine detail, spacing, registration and proximity to cuts or folds. Avoid treating every small screen element as suitable for a physical tool or coating. Ask for specific artwork changes where the selected process needs them.'),('Approve the finished combination','The paper, ink, coating and finish work together. Review the surface under useful lighting and handle the formed package. Check cracking or rubbing where these are relevant to the design. If the sample uses a different material or finish route, record which decisions remain open instead of calling it a final standard.')],
 example='Illustrative buying scenario: a fragrance buyer wants emphasis on a front-panel logo. The team compares a metallic foil reference, a selective gloss reference and a raised paper reference on suitable substrates. The buyer chooses the desired effect, then reviews a production proposal and artwork layers for that route. No invented test scores or claims about universal finish durability are needed to make the comparison useful.',
 rows=[('Foil stamping','Choose for a selected foil effect; review coverage, edge detail and registration.'),('Spot UV','Choose for localized surface contrast; review gloss, substrate and coating compatibility.'),('Embossing','Choose for raised relief; review paper behavior, tooling and the reverse face.')],
 mistakes=['Expecting a digital render to establish texture.','Placing critical finish details across folds without review.','Approving a finish sample without recording its substrate.'],
 checks=['Provide distinct print and finish layers.','Review artwork at actual size.','Identify the physical appearance reference and any sample limitations.'],
 faq=[('Can I combine these finishes?','Ask for a process review on the selected construction. The combination needs artwork, registration and sample approval; availability should be confirmed in the quotation.'),('Will foil look identical on every material?','Review the chosen foil and substrate together. Surface and lighting affect appearance, so keep a physical reference for the intended combination.'),('Is embossing the same as debossing?','Embossing raises the relief; debossing presses it inward. Clarify the viewing face and desired effect in the artwork brief.'),('Which finish is least expensive?','Request comparable quotations for the actual area, quantity, substrate and setup. There is no reliable universal price order for every project.')],
 links=['/materials/printing-finishes/','/guides/packaging-print-proof/']),
 dict(slug='cosmetic-packaging-buyers-guide', title='Cosmetic packaging: a buyer’s carton and gift-box guide',
 description='Specify cosmetic cartons and gift boxes around bottles, jars and tubes, with inserts, artwork checks, sample fit and shipping protection.',
 answer='Start a cosmetic packaging brief with the filled product, closure, dimensions, weight and sales channel. Compare a folding carton for the retail unit, a rigid box for a presentation set and an outer shipper for transit. Select inserts, print and finishes around that job. Decorative secondary packaging does not establish compatibility or compliance of the primary cosmetic container.',
 chapters=[('Measure the complete filled product','Include the cap, pump, collar or other protruding part. State the orientation and whether a protective sleeve or bag stays on the item. For a set, list every component and the order in which the customer should remove them. Request an assembled fit sample before artwork is locked.'),('Plan the information panels','Reserve space for product wording, variant identification, barcodes and any required copy supplied by the product owner. Keep important text clear of folds, glue areas and hidden surfaces. Review the final copy at actual size and on the assembled pack; attractive front-panel artwork is only one part of the approval.'),('Separate retail presentation from transit','A polished retail box may still need cushioning and an outer carton. Identify the parcel configuration and distribution route. Review product movement, contact surfaces and the way staff load the items. Test requirements should describe that complete configuration rather than an empty decorative box.')],
 example='Illustrative buying scenario: a brand has a tall pump bottle and a smaller jar. It reviews individual folding cartons for retail and a two-item rigid gift set for gifting. The set has a proposed insert with separate retention points and removal space. The buyer checks both products in the sample, then reviews an outer parcel configuration. This describes a purchasing method, not a customer relationship or tested outcome.',
 rows=[('Individual retail carton','Review product clearance, display panels, closure and packing access.'),('Presentation gift set','Review insert retention, removal, opening order and surface contact.'),('Courier parcel','Review the loaded outer pack, movement, closure and distribution checks.')],
 mistakes=['Measuring the bottle without its pump or cap.','Assuming the gift box replaces shipping protection.','Treating secondary packaging as evidence for formula compatibility.'],
 checks=['Send dimensions of each complete product.','Approve text and artwork on the assembled structure.','Record insert, outer packaging and test requirements separately.'],
 faq=[('Should I choose a carton or rigid box?','Compare the sales format, opening experience, insert, quantity and shipment volume. A single retail product and a multi-item gift set can require different structures.'),('Can I use a foil logo?','Share the logo and effect reference, then review the artwork and selected surface. Confirm the process in the quotation and approve an appropriate sample.'),('Can one box hold several variants?','Check the smallest and largest products and any retention or identification differences. A common outer size may still need variant-specific inserts or artwork.'),('What should the first enquiry include?','Provide product photos, complete dimensions, weight, quantities by variant, retail or gifting use, delivery country and artwork status.')],
 links=['/industries/beauty-skincare/','/services/structural-design/']),
 dict(slug='apparel-packaging-selection', title='Apparel packaging: choose bags, mailers, boxes and tags',
 description='Coordinate apparel bags, ecommerce mailers, gift boxes and hang tags using folded garment dimensions, packing workflow and artwork approvals.',
 answer='Choose apparel packaging around the folded garment, sales channel and packing workflow. Retail paper bags carry a purchase, mailers contain a shipment, gift boxes organize presentation and tags communicate product information. Specify each component separately, then check the complete set together. A coordinated graphic identity does not mean every component should use the same material or dimensions.',
 chapters=[('Begin with the packed garment','Measure the garment as staff will actually fold it, including protective bags, tissue or accessories. Compare the smallest and largest variants. Leave working room for packing and removal without creating unnecessary movement. A photograph of an unfolded garment is not sufficient to approve the finished package size.'),('Define each component’s job','List the retail bag, garment bag, mailer, box, tag, card and seal only where the purchase journey needs them. State which components travel together. Include handle comfort for carry bags, closure for mailers and attachment for tags. This prevents a visually coordinated set from failing at the packing station.'),('Coordinate appearance across surfaces','Share artwork versions and physical color references. Paper, coated board, film and card can produce different appearances from the same artwork values. Review a representative set together and record which reference governs each material. Final text, sizes, care information and codes should be approved by the product owner.')],
 example='Illustrative buying scenario: an apparel buyer prepares a paper bag and hang tag for retail, plus a protective garment bag and outer mailer for online orders. A separate gift-box option is assessed for a seasonal set. Staff pack the folded garments and accessories into each proposed combination. The buyer compares fit and handling before approving the coordinated artwork, rather than ordering every component from a mood board alone.',
 rows=[('Retail carry bag','Specify folded contents, handle direction, carrying conditions and print.'),('Ecommerce pack','Specify garment protection, outer closure, label placement and return workflow.'),('Tags and inserts','Specify dimensions, attachment, print, text and how they sit in the complete pack.')],
 mistakes=['Using garment size labels as package dimensions.','Leaving tag attachment out of the specification.','Expecting matching color values to look identical on film and paper.'],
 checks=['Trial the actual folded garments and accessories.','List quantities per component, size and artwork.','Approve the complete graphic set with clear material references.'],
 faq=[('Can one size cover every garment?','Compare the packed dimensions of the full range. A common size can simplify the order but may leave too much movement or make larger items difficult to pack.'),('Do paper bags replace shipping mailers?','Their jobs differ. A retail bag must be assessed separately from the closed parcel and its distribution requirements.'),('Should tags and bags use the same print colors?','They can share a brand direction, but material and print differences need review. Compare physical references together rather than relying only on screen values.'),('What should I send for a coordinated quote?','Send folded garment dimensions, a component list, quantities per size and artwork, delivery market and any reference images or existing brand standards.')],
 links=['/industries/apparel/','/services/multi-product-sourcing/']),
 dict(slug='prepare-packaging-dielines', title='Packaging dielines: how to prepare artwork for approval',
 description='Prepare packaging artwork with an identified dieline, separate cut and fold guides, finish layers, copy checks and a recorded approval revision.',
 answer='A packaging dieline is the flat structural drawing used to locate panels, cuts, creases and assembly areas. Start artwork on the supplier-confirmed drawing for the selected construction and size. Keep structural guides separate from print artwork, identify glue or seal zones and agree bleed and safe areas with prepress. Approve the assembled structure and the final artwork revision together.',
 chapters=[('Confirm structure before decorating it','Label the panel map, front, opening and measurement convention. Use a fit sample to resolve product clearance and insert requirements before final artwork placement. Resizing a graphic does not automatically preserve the structure, closure or material allowance. Ask for a revised dieline when dimensions change.'),('Prepare files for a specific print route','Supply editable artwork and a viewing PDF where requested. Keep fonts, linked images, color references and special finishes identifiable. Ask prepress for the required bleed, image resolution and minimum detail for the actual process rather than applying one generic number to every material. Mark non-printing guides clearly.'),('Review both flat and assembled views','Check orientation, hidden panels, text across folds and any copy near the glue or seal area. Inspect codes at final size and in their intended location. Record who approves wording, graphics and structure. When a file changes, give it a new revision and review the affected decisions before production preparation.')],
 example='Illustrative buying scenario: a buyer receives a folding-carton drawing and places a logo, ingredients panel and barcode. During the assembled review, the team finds that a seam would hide part of the copy. The artwork is revised on the same confirmed structural drawing, with a new file reference and approval. This workflow example describes an avoidable layout problem without claiming an actual customer incident.',
 rows=[('Structural file','Identify dimensions, panel map, cuts, creases, glue zones and revision.'),('Print artwork','Identify color references, images, fonts, text and process-specific allowances.'),('Finish layers','Separate foil, coating or relief positions and review registration with prepress.')],
 mistakes=['Building final artwork on an unconfirmed internet template.','Flattening cutting guides into the printed image.','Reusing an approval after changing size or content.'],
 checks=['Match the artwork to the approved dieline revision.','Review a full-size PDF and assembled sample.','Record final wording, codes and finish-layer approval.'],
 faq=[('Can I design before receiving a dieline?','You can explore a visual direction, but final production artwork should use the confirmed drawing. A concept image does not specify cutting and assembly.'),('What bleed should I use?','Ask the prepress team for the allowance required by the chosen structure, material and print process. Do not assume one setting covers every package.'),('Is a PDF enough?','A viewing PDF is useful for review. Confirm whether editable files, fonts, images and separate finish layers are also needed for production preparation.'),('Does artwork approval confirm package fit?','No. Fit needs review with the assembled construction and actual contents. Record structural and printed appearance approvals separately when they use different samples.')],
 links=['/services/artwork-preflight/','/guides/packaging-print-proof/']),
 dict(slug='choose-packaging-supplier-china', title='How to choose a packaging supplier in China: checklist',
 description='Compare packaging suppliers by supplying entity, specification, sample scope, documentation, inspection and the full quotation basis.',
 answer='Compare packaging suppliers using the same written specification, an identified supplying company and samples that answer your project’s risks. Ask who makes each component, what the quotation includes, which documents support important claims and how inspection and shipment responsibilities are agreed. A polished website, a low unit price or a certificate image alone is not enough to approve a supplier.',
 chapters=[('Identify the company and scope','Ask for the legal supplying name and clarify manufacturing, sourcing and subcontracting responsibilities. Match the quotation and commercial paperwork to the intended supplier. Where several companies or sites are involved, request a clear component-level responsibility map rather than assuming every product comes from one facility.'),('Compare evidence at the right level','Ask to review relevant production capabilities, sample construction and order-specific documents. If a certificate matters, check the issuing record and scope rather than relying on a cropped logo. If performance matters, request the construction, method, conditions and acceptance criteria behind the claim. Evidence for a different material or order may not answer your requirement.'),('Make the commercial comparison explicit','Keep dimensions, material, artwork, quantity, samples, packing and delivery basis consistent across quotes. Identify tooling, freight and inspection responsibilities separately. Agree change control, nonconformity handling and the reference that governs release. Obtain specialist advice where a transaction or destination requirement calls for it.')],
 example='Illustrative buying scenario: a buyer receives three quotations for a gift-box range. The buyer discovers that one includes assembly, another assumes flat supply and another omits freight. The team requests revised quotes using the same specification, then reviews the proposed samples and the supplying entity. The revised comparison supports a decision without inventing supplier rankings, savings or customer endorsements.',
 rows=[('Business identity','Confirm the supplying company, contact route and responsibility for each component.'),('Technical proposal','Compare the same material, structure, sample scope and evidence requirements.'),('Commercial terms','Compare inclusions, delivery basis, payment conditions, inspection and change handling.')],
 mistakes=['Treating the cheapest unit price as the lowest complete order cost.','Assuming a certificate covers every product and process.','Leaving sample limitations and release responsibility unstated.'],
 checks=['Keep an agreed specification with each comparable quotation.','Verify the scope of documents important to your order.','Record the approved sample and how later changes will be handled.'],
 faq=[('Must a supplier own every production step?','Assess whether the proposed responsibility, coordination and evidence fit your project. Ask explicitly which work is performed by which company rather than inferring ownership.'),('How should I review an FSC claim?','Use the current official certificate record and request the relevant order claim and documentation. A certificate image should not be treated as proof that every offered item is FSC-labelled.'),('Are samples enough to approve a bulk order?','Identify what each sample represents and agree production checks. A sample is useful evidence for specific decisions, not proof of every future item or delivery condition.'),('What should I ask PackHubGlobe?','Review the About and Factory pages, then request a quotation identifying the supplying company, specification, samples, inspection requirements and delivery basis for your project.')],
 links=['/about/','/services/quality-control/']),
 dict(slug='custom-paper-bags-guide', title='Custom paper bags: materials, handles and print finishes',
 description='Specify custom paper bags by contents, dimensions, paper, handle attachment, reinforcement, artwork and carrying checks with the intended load.',
 answer='Specify a custom paper bag as a complete carrying system: paper, dimensions, side and base construction, handle attachment, reinforcement and print finish. Begin with the actual contents and carrying conditions. Choose appearance and handles alongside a loaded sample review; paper weight alone does not establish bag strength. Confirm the construction and required checks in the written specification.',
 chapters=[('Measure the load and the opening','List every item that travels in the bag, including tissue, an inner box or protective wrap. Include the space needed to place and remove the contents. Check whether handles obstruct the opening and how the bag sits when loaded. Give width, gusset and height conventions explicitly to avoid comparing differently measured bags.'),('Review paper and handles together','Kraft and coated-paper directions create different visual and print choices. Twisted paper, flat paper, ribbon or rope-style handles also change comfort and attachment details. Review the proposed combinations rather than choosing a handle photograph separately from the bag structure. Ask which reinforcement is included at the top and base.'),('Check the finished bag in use','Use representative contents and agreed carrying conditions. Look for stress at handle attachments, seams, folds and contact with sharp product corners. If humidity or repeated handling matters, include it in the review plan. Keep results tied to the tested construction; do not turn one demonstration into an unlimited load guarantee.')],
 example='Illustrative buying scenario: a gift buyer needs a bag for a boxed candle and a small card. The buyer compares a kraft-paper direction and a coated-paper direction with suitable handle proposals. Both are reviewed with the same complete contents, including the box corners and packing tissue. The selected construction and artwork are then recorded for the quote. No invented lifting result is necessary to explain the decision.',
 rows=[('Paper and finish','Compare appearance, print coverage, coating and the complete material construction.'),('Handle system','Compare comfort, attachment, top reinforcement and opening clearance.'),('Loaded bag','Compare base support, seams, content movement and intended carrying conditions.')],
 mistakes=['Choosing bag height without allowing for handle attachment.','Approving paper weight as a complete carrying specification.','Using an empty-bag photograph as evidence of load performance.'],
 checks=['Pack all intended contents in an assembled sample.','Record paper, handles, reinforcement and finish together.','Agree load review conditions and how construction changes are assessed.'],
 faq=[('What dimensions should I send?','Send the contents and required usable space, then identify width, gusset and height with units. Clarify whether measurements are internal or finished external values.'),('Which handle is strongest?','Compare the complete bag and attachment under the intended load. Handle material alone does not establish a finished bag’s carrying performance.'),('Can I add foil or embossing?','Request a review of the chosen paper, artwork and finish position. Approve a suitable physical reference and confirm the final process in the quote.'),('Does a kraft bag prove an environmental claim?','No. Ask for evidence relevant to the complete construction and the specific claim. Color and surface appearance are not sourcing or recyclability documentation.')],
 links=['/products/paper-bags/','/guides/paper-bag-load-testing/']),
]
